periods.description:
@@preprocessing
<%_ {
const __data=getMessageVar('stat_data',{defaults:{}});
const __frontier=Math.max(1,..._.get(__data,['世界','已解鎖樓層'],[1]).map(Number).filter(Number.isFinite));
const __name="微笑棺木";
const __id="organization-laughing-coffin";
const __record=_.get(__data,['世界','組織',__id],null);
const __state=String(_.get(__record,'狀態',''));
const __ended=['解散','覆灭','合并','消失'].includes(__state);
const __override=_.get(__data,['世界','事件','organization-timeline-exception','旗標',__id],false)===true;
const __planned=_.get(__data,['世界','事件','organization-preparation','旗標',__id],false)===true;
const __date=String(_.get(__data,'世界.日期','0000-00-00'));
const __isFormal=/正式|公会/.test(String(_.get(__record,'形態',_.get(__record,'類型',''))));
const __minimum=__isFormal?3:3;
const __specialOk=_.get(__data,['世界','事件','组织前置','微笑棺木成立事件'],false)===true;
const __evidence=Array.isArray(__record?.成立依據)?__record.成立依據.filter(Boolean):[];
const __confirmed=__record?.成立確認===true&&!!String(__record?.成立事件ID||'').trim()&&__evidence.length>=2;
const __recordDateOk=!__record?.成立日期||String(__record.成立日期)<=__date;
const __eligible=__override||(__frontier>=__minimum&&(__date>='2024-01-01')&&__recordDateOk&&__specialOk);
const __active=!!__record&&__confirmed&&!__ended&&__eligible&&!['籌備中','候選','未成立'].includes(__state);
if(__active){ _%>
<ORGANIZATION_GATE name="微笑棺木" status="<%- __state || '活动中' %>" frontier="<%- __frontier %>" date="<%- __date %>">
<SAO_ORGANIZATION>
# 微笑棺木
## 原作定位
由PoH等煽动者、杀人玩家与受胁迫成员形成的犯罪集团。

## 结构与资源
采用分散小队、假身份、联络人、隐蔽据点和共同罪行维持控制。 资源、据点、成员、资金和当前行动必须读取已经建立的世界.組織；静态资料不能覆盖游玩历史。

## 常见行动
诱导PK、麻痹伏击、黑市销赃、招募边缘玩家与逃避攻略组追捕。

## 时间锚点
低层可以存在摩鲁特、黑斗篷煽动者、独立橙名或犯罪网络前身；在成立事件前禁止使用微笑棺木正式组织名。

## 连续性
成员死亡、退会、分裂、合并、赔偿、据点迁移和玩家介入都持续生效。当前世界.組織优先，禁止恢复已经改变的原作状态。
</SAO_ORGANIZATION>
</ORGANIZATION_GATE>
<%_ }else if(__record&&__ended&&__confirmed){ _%>
<ORGANIZATION_GATE name="微笑棺木" status="<%- __state %>" frontier="<%- __frontier %>" date="<%- __date %>">
该组织只保留历史影响，不能生成现役职位、制服、据点命令或新成员身份。
</ORGANIZATION_GATE>
<%_ }else if(__record&&(!__eligible||(__record?.成立日期&&!__recordDateOk))){ _%>
<ORGANIZATION_GATE name="微笑棺木" status="时间线冲突" frontier="<%- __frontier %>" date="<%- __date %>">
当前记录未通过楼层、日期或成立前提，禁止让该组织以现役身份行动。玩家实际改变世界线时，先完成成立事件并写入对应时间线例外旗标。
成立前提：已经发生共同杀人、正式命名、联络规则与圈外据点建立；原作日期锚点为2024-01-01。
</ORGANIZATION_GATE>
<%_ }else if((__planned||__state==='籌備中')&&__eligible&&!__confirmed){ _%>
<ORGANIZATION_GATE name="微笑棺木" status="筹备中" frontier="<%- __frontier %>" date="<%- __date %>">
当前只允许描写命名、合并、成员同意、资源承诺和规则确认。成立事件完成后，同轮向 /世界/組織/organization-laughing-coffin 写入完整档案与至少两条成立依据；下一轮才可按现役组织行动。
成立前提：已经发生共同杀人、正式命名、联络规则与圈外据点建立；原作日期锚点为2024-01-01。
</ORGANIZATION_GATE>
<%_ }else if(__record&&!__confirmed){ _%>
<ORGANIZATION_GATE name="微笑棺木" status="证据不足" frontier="<%- __frontier %>" date="<%- __date %>">
记录缺少成立确认、唯一成立事件ID或至少两条成立依据。禁止生成现役制服、职位、据点命令、成员身份和集体行动。
成立前提：已经发生共同杀人、正式命名、联络规则与圈外据点建立；原作日期锚点为2024-01-01。
</ORGANIZATION_GATE>
<%_ }else{ _%>
<ORGANIZATION_GATE name="微笑棺木" status="尚未成立" frontier="<%- __frontier %>" date="<%- __date %>">
禁止提前生成该组织的制服、据点、职位、命令或成员身份。名称被提及时只能视为提议、传闻或元信息。
成立前提：已经发生共同杀人、正式命名、联络规则与圈外据点建立；原作日期锚点为2024-01-01。
</ORGANIZATION_GATE>
<%_ } } _%>


V5變量規則：只有成立事件被確認後，才以固定ID `organization-laughing-coffin` 建立 `/世界/組織/organization-laughing-coffin`；名稱只作顯示。
